    "content": "/**\n * GENERATED FILE — do not edit by hand.\n * Built by scripts/build_quote_font.js from DejaVu Sans (Bitstream Vera licence).\n *\n * 8-bit anti-aliased coverage atlas, deflated with the project's own encoder.\n * Glyph entry: [x, y, width, height, bearingX, bearingY, advance]\n *   bearingX — pen origin → first ink column\n *   bearingY — baseline → top of ink\n * All units are pixels at em = 64.\n */\nexport const FONT_EM = 64;\nexport const ATLAS_WIDTH = 900;\nexport const ATLAS_HEIGHT = 201;\nexport const ATLAS_DEFLATED_BASE64 = '';\n\nexport const GLYPHS = {\"0\":[480,1,33,49,4,48,41],\"1\":[423,67,28,47,7,47,41],\"2\":[182,67,31,48,4,48,41],\"3\":[514,1,32,49,4,48,41],\"4\":[452,67,35,47,3,47,41],\"5\":[214,67,32,48,4,47,41],\"6\":[547,1,33,49,4,48,41],\"7\":[247,67,31,48,5,48,41],\"8\":[581,1,33,49,4,48,41],\"9\":[615,1,33,49,4,48,41],\" \":[0,0,0,0,0,0,20],\"!\":[415,67,7,47,9,47,26],\"\\\"\":[111,165,18,18,6,47,29],\"#\":[267,117,45,46,4,46,54],\"$\":[93,1,31,59,5,49,41],\"%\":[379,1,55,49,3,48,61],\"&\":[435,1,44,49,4,48,50],\"'\":[130,165,6,18,6,47,18],\"(\":[155,1,15,57,5,49,25],\")\":[171,1,15,57,5,49,25],\"*\":[40,165,28,30,2,48,32],\"+\":[337,117,41,41,6,41,54],\",\":[178,165,10,16,5,9,20],\"-\":[257,165,17,6,3,21,23],\".\":[248,165,8,8,6,8,20],\"/\":[289,1,22,53,0,47,22],\":\":[31,165,8,33,7,33,22],\";\":[379,117,10,41,5,34,22],\"<\":[723,117,41,35,6,38,54],\"=\":[69,165,41,19,6,30,54],\">\":[765,117,41,35,6,38,54],\"?\":[279,67,26,48,4,48,34],\"@\":[187,1,56,57,4,46,64],\"A\":[488,67,44,47,0,47,44],\"B\":[533,67,34,47,6,47,44],\"C\":[649,1,39,49,3,48,45],\"D\":[568,67,40,47,6,47,49],\"E\":[609,67,31,47,6,47,40],\"F\":[306,67,28,48,6,47,37],\"G\":[689,1,42,49,3,48,50],\"H\":[641,67,36,47,6,47,48],\"I\":[678,67,7,47,6,47,19],\"J\":[23,1,17,60,-4,47,19],\"K\":[686,67,38,47,6,47,42],\"L\":[725,67,30,47,6,47,36],\"M\":[756,67,43,47,6,47,55],\"N\":[800,67,36,47,6,47,48],\"O\":[732,1,44,49,3,48,50],\"P\":[837,67,31,47,6,47,39],\"Q\":[244,1,44,57,3,48,50],\"R\":[1,117,37,47,6,47,44],\"S\":[777,1,34,49,4,48,41],\"T\":[335,67,41,48,-1,48,39],\"U\":[377,67,37,48,5,47,47],\"V\":[39,117,44,47,0,47,44],\"W\":[84,117,60,47,2,47,63],\"X\":[145,117,40,47,2,47,44],\"Y\":[186,117,40,47,0,47,39],\"Z\":[227,117,39,47,2,47,44],\"[\":[125,1,14,58,5,49,25],\"\\\\\":[0,0,0,0,0,0,22],\"]\":[140,1,14,58,6,49,25],\"^\":[137,165,40,18,7,47,54],\"_\":[275,165,34,5,-1,-10,32],\"`\":[189,165,16,12,5,52,32],\"a\":[390,117,31,37,3,36,39],\"b\":[312,1,33,50,5,49,41],\"c\":[422,117,29,37,3,36,35],\"d\":[346,1,32,50,3,49,41],\"e\":[452,117,33,37,3,36,39],\"f\":[812,1,23,49,1,49,23],\"g\":[836,1,32,49,3,36,41],\"h\":[1,67,31,49,5,49,41],\"i\":[33,67,6,49,6,49,18],\"j\":[8,1,14,62,-2,49,18],\"k\":[40,67,32,49,5,49,37],\"l\":[73,67,6,49,6,49,18],\"m\":[549,117,52,36,5,36,62],\"n\":[602,117,31,36,5,36,41],\"o\":[486,117,33,37,3,36,39],\"p\":[80,67,33,49,5,36,41],\"q\":[114,67,32,49,3,36,41],\"r\":[634,117,22,36,5,36,26],\"s\":[520,117,28,37,3,36,33],\"t\":[313,117,23,45,1,45,25],\"u\":[657,117,30,36,5,35,41],\"v\":[807,117,34,35,2,35,38],\"w\":[842,117,48,35,2,35,52],\"x\":[688,117,34,36,2,36,38],\"y\":[147,67,34,49,2,36,38],\"z\":[1,165,29,35,2,35,34],\"{\":[41,1,25,60,8,49,41],\"|\":[1,1,6,65,8,49,22],\"}\":[67,1,25,60,8,49,41],\"~\":[206,165,41,11,6,25,54]};\n"
